package handover

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Service 在 Store 之上实现班次交接的全部业务规则。
type Service struct {
	store *Store
	now   func() time.Time
}

// NewService 创建业务服务。
func NewService(store *Store) *Service {
	return &Service{store: store, now: time.Now}
}

// nowAt 供测试固定处理时间。
func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }

func clean(s string) string { return strings.TrimSpace(s) }

func requireNonEmpty(field, v string) error {
	if clean(v) == "" {
		return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
	}
	return nil
}

func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
	// 前班结束恰好等于后班开始（端点相等）不算重叠。
	return s1.Before(e2) && s2.Before(e1)
}

// notePair 返回无序班次编号对，作为重叠说明的稳定键。
func notePair(a, b string) (string, string) {
	if a <= b {
		return a, b
	}
	return b, a
}

func findShift(d *Data, id string) (*Shift, int) {
	for i := range d.Shifts {
		if d.Shifts[i].ID == id {
			return &d.Shifts[i], i
		}
	}
	return nil, -1
}

func findItem(d *Data, id string) (*Item, int) {
	for i := range d.Items {
		if d.Items[i].ID == id {
			return &d.Items[i], i
		}
	}
	return nil, -1
}

func findHandover(d *Data, id string) (*Handover, int) {
	for i := range d.Handovers {
		if d.Handovers[i].ID == id {
			return &d.Handovers[i], i
		}
	}
	return nil, -1
}

func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
	for i := range h.Entries {
		if h.Entries[i].ItemID == itemID {
			return &h.Entries[i], i
		}
	}
	return nil, -1
}

func findNote(d *Data, a, b string) *OverlapNote {
	x, y := notePair(a, b)
	for i := range d.Notes {
		if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
			return &d.Notes[i]
		}
	}
	return nil
}

// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
func currentItemsOfShift(d *Data, shiftID string) []Item {
	out := []Item{}
	seen := map[string]bool{}
	for _, it := range d.Items {
		if seen[it.ID] {
			continue
		}
		if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
			seen[it.ID] = true
			out = append(out, it)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// hasEffectiveNote 报告两个班次之间是否已保存至少一条有效重叠说明：
// 正文去掉首尾空白后仍有内容。记录存在但正文缺失、为空或全是空白
// （空格、制表符、换行）都不算已说明；与存放次序无关，只认有效正文。
func hasEffectiveNote(d *Data, a, b string) bool {
	x, y := notePair(a, b)
	for i := range d.Notes {
		if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y && clean(d.Notes[i].Note) != "" {
			return true
		}
	}
	return false
}

// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
// 不同岗位互不影响。
func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
	position = clean(position)
	owner = clean(owner)
	overlapNote = clean(overlapNote)
	if err := requireNonEmpty("岗位", position); err != nil {
		return Shift{}, err
	}
	if err := requireNonEmpty("负责人", owner); err != nil {
		return Shift{}, err
	}
	if !end.After(start) {
		return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
			ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
	}

	var created Shift
	err := svc.store.mutate(func(d *Data) error {
		var overlapping []Shift
		for _, sh := range d.Shifts {
			if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
				overlapping = append(overlapping, sh)
			}
		}
		if len(overlapping) > 0 && overlapNote == "" {
			ids := make([]string, len(overlapping))
			for i, sh := range overlapping {
				ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
			}
			return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
				ErrOverlap, strings.Join(ids, "、"))
		}

		d.ShiftSeq++
		now := svc.now()
		created = Shift{
			ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
			Position:  position,
			Owner:     owner,
			Start:     start,
			End:       end,
			CreatedAt: now,
		}
		d.Shifts = append(d.Shifts, created)

		// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
		for _, sh := range overlapping {
			if findNote(d, created.ID, sh.ID) != nil {
				continue
			}
			d.NoteSeq++
			x, y := notePair(created.ID, sh.ID)
			d.Notes = append(d.Notes, OverlapNote{
				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
				Position:  position,
				ShiftA:    x,
				ShiftB:    y,
				Note:      overlapNote,
				CreatedAt: now,
			})
		}
		return nil
	})
	if err != nil {
		return Shift{}, err
	}
	// 返回独立副本：调用方保留的建立结果（关闭时间等指针字段）不与系统
	// 保存的班次共享内存。
	return cloneShift(created), nil
}

// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
	note = clean(note)
	if err := requireNonEmpty("重叠说明", note); err != nil {
		return OverlapNote{}, err
	}
	if clean(shiftA) == clean(shiftB) {
		return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
	}

	var saved OverlapNote
	err := svc.store.mutate(func(d *Data) error {
		sa, _ := findShift(d, clean(shiftA))
		sb, _ := findShift(d, clean(shiftB))
		if sa == nil || sb == nil {
			return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
		}
		if sa.Position != sb.Position {
			return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
				ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
		}
		if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
			return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
				ErrInvalidInput, sa.ID, sb.ID)
		}
		d.NoteSeq++
		x, y := notePair(sa.ID, sb.ID)
		saved = OverlapNote{
			ID:        fmt.Sprintf("N%03d", d.NoteSeq),
			Position:  sa.Position,
			ShiftA:    x,
			ShiftB:    y,
			Note:      note,
			CreatedAt: svc.now(),
		}
		d.Notes = append(d.Notes, saved)
		return nil
	})
	return saved, err
}

// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
	shiftID = clean(shiftID)
	content = clean(content)
	constraints = clean(constraints)
	followOwner = clean(followOwner)
	if err := requireNonEmpty("事项内容", content); err != nil {
		return Item{}, err
	}
	if err := requireNonEmpty("后续负责人", followOwner); err != nil {
		return Item{}, err
	}
	if !severity.valid() {
		return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
	}

	var created Item
	err := svc.store.mutate(func(d *Data) error {
		sh, _ := findShift(d, shiftID)
		if sh == nil {
			return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
		}
		if sh.Closed {
			return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
		}
		d.ItemSeq++
		now := svc.now()
		created = Item{
			ID:             fmt.Sprintf("I%03d", d.ItemSeq),
			OriginShiftID:  sh.ID,
			ShiftIDs:       []string{sh.ID},
			CurrentShiftID: sh.ID,
			Content:        content,
			Severity:       severity,
			Constraints:    constraints,
			FollowOwner:    followOwner,
			CreatedAt:      now,
			Events: []ItemEvent{
				{At: now, Kind: "created", Detail: "事项建立"},
			},
		}
		d.Items = append(d.Items, created)
		return nil
	})
	if err != nil {
		return Item{}, err
	}
	// 返回独立副本：调用方保留的新增结果与系统保存的事项脱离，
	// 改动结果不影响存储，也不会在后续正常保存时被带进存储。
	return cloneItem(created), nil
}

// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
// 只有本地数据保存成功才算修改完成：写盘失败时内存变更随快照一并回滚，
// 返回错误与零值事项，不把尚未保存的新值当作修改结果。
func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
	itemID = clean(itemID)
	content = clean(content)
	constraints = clean(constraints)
	followOwner = clean(followOwner)
	if err := requireNonEmpty("事项内容", content); err != nil {
		return Item{}, err
	}
	if err := requireNonEmpty("后续负责人", followOwner); err != nil {
		return Item{}, err
	}
	if !severity.valid() {
		return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
	}

	var updated Item
	err := svc.store.mutate(func(d *Data) error {
		it, _ := findItem(d, itemID)
		if it == nil {
			return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
		}
		sh, _ := findShift(d, it.CurrentShiftID)
		if sh == nil || sh.Closed {
			return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
				ErrShiftClosed, itemID, it.CurrentShiftID)
		}
		changes := []string{}
		if it.Content != content {
			changes = append(changes, "内容")
		}
		if it.Severity != severity {
			changes = append(changes, "严重程度")
		}
		if it.Constraints != constraints {
			changes = append(changes, "限制条件")
		}
		if it.FollowOwner != followOwner {
			changes = append(changes, "后续负责人")
		}
		it.Content = content
		it.Severity = severity
		it.Constraints = constraints
		it.FollowOwner = followOwner
		it.Events = append(it.Events, ItemEvent{
			At:     svc.now(),
			Kind:   "updated",
			Detail: "修改字段：" + joinOr(changes, "无变更"),
		})
		updated = *it
		return nil
	})
	if err != nil {
		// 保存失败时内存已回滚，不能把尚未保存的新值当作修改结果返回。
		return Item{}, err
	}
	// 返回独立副本：调用方保留的修改结果不与系统保存的事项共享内存。
	return cloneItem(updated), nil
}

func joinOr(xs []string, or string) string {
	if len(xs) == 0 {
		return or
	}
	return strings.Join(xs, "、")
}

// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
// 只有本地数据保存成功才算关闭完成：写盘失败时内存变更随快照一并回滚，
// 返回错误与零值事项，不把尚未保存的关闭状态当作关闭结果。
func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
	itemID = clean(itemID)
	operator = clean(operator)
	if err := requireNonEmpty("操作人", operator); err != nil {
		return Item{}, err
	}

	var closed Item
	err := svc.store.mutate(func(d *Data) error {
		it, _ := findItem(d, itemID)
		if it == nil {
			return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
		}
		if it.Closed {
			return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
		}
		sh, _ := findShift(d, it.CurrentShiftID)
		if sh == nil || sh.Closed {
			return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
				ErrShiftClosed, itemID, it.CurrentShiftID)
		}
		now := svc.now()
		it.Closed = true
		it.ClosedAt = &now
		it.CloseOperator = operator
		it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
		closed = *it
		return nil
	})
	if err != nil {
		// 保存失败时内存已回滚，不能把尚未保存的关闭状态当作关闭结果返回。
		return Item{}, err
	}
	// 返回独立副本：调用方保留的关闭结果（含关闭时间）与系统保存的事项脱离；
	// 班次结束后再改写这份结果中的关闭时刻，结束时记录里保留的仍是当时的值。
	return cloneItem(closed), nil
}

// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
// 交接视为已完成，可以结束。
// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
// 事项归属与已保存的处理经过。
// 只有本地数据保存成功才算结束完成：写盘失败时内存变更随快照一并回滚，
// 保留原保存错误并返回零值班次（无编号、无结束状态、无结束时间、无结束时
// 事项记录，空清单班次同样如此），不把尚未保存的结束状态或失败前查询到的
// 进行中班次当作结束结果返回。
// 返回的班次结果是成功结束时的独立副本（关闭时间与结束时记录均深拷贝）：
// 调用方为本地展示改动结果（实际结束时刻、事项内容、清单项、关闭时间等）
// 只影响手中的结果，不改变系统保存的结束时事实，也不随之后的正常保存被带进
// 存储；先取得的另一份结果同样互不影响。
func (svc *Service) CloseShift(shiftID string) (Shift, error) {
	shiftID = clean(shiftID)
	var result Shift
	err := svc.store.mutate(func(d *Data) error {
		sh, _ := findShift(d, shiftID)
		if sh == nil {
			return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
		}
		if sh.Closed {
			return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
		}
		for i := range d.Handovers {
			h := &d.Handovers[i]
			if h.ToShiftID == sh.ID && !h.Completed() {
				return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
					ErrHandoverState, h.ID)
			}
		}
		now := svc.now()
		sh.Closed = true
		sh.ClosedAt = &now

		// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
		// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。每项指针
		// （关闭时间）都复制一份：结束时记录保留这次成功结束时的事实，既不与
		// 事项当前记录共享内存，也不与交给调用方的结果共享内存。
		record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
		for i := range d.Items {
			it := &d.Items[i]
			if it.CurrentShiftID != sh.ID {
				continue
			}
			record.Items = append(record.Items, CloseItemSnapshot{
				ItemID:        it.ID,
				Content:       it.Content,
				Severity:      it.Severity,
				Constraints:   it.Constraints,
				FollowOwner:   it.FollowOwner,
				Closed:        it.Closed,
				ClosedAt:      cloneTimePtr(it.ClosedAt),
				CloseOperator: it.CloseOperator,
			})
		}
		sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
		sh.CloseRecord = record

		// 返回独立副本：调用方改写自己保留的结果不能影响系统保存的结束时记录。
		result = cloneShift(*sh)
		return nil
	})
	if err != nil {
		// 业务拒绝或保存失败时不返回任何班次结果：保存失败时内存已回滚，
		// 不能把尚未保存的结束状态当作结束结果交给调用方。
		return Shift{}, err
	}
	return result, nil
}

// CreateHandover 由交班班次向同岗位接班班次发起交接。
// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
// 要求仅对首次发起生效。
// 只有本地数据保存成功才算发起完成：首次发起的输入与班次状态均合法、实际进入
// 保存阶段后写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果
// （编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单没有事项），
// 不把尚未保存的编号、发起时间、清单或空清单的完成时间当作发起结果；失败尝试
// 不占用交接编号，也不留下已指定接班对象的关系。
func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
	fromShiftID = clean(fromShiftID)
	toShiftID = clean(toShiftID)

	var result Handover
	// saved 标记业务变更是否已完整执行、只待落盘：此后出现的错误只能是保存
	// 阶段失败，而不是业务拒绝。
	saved := false
	err := svc.store.mutate(func(d *Data) error {
		from, _ := findShift(d, fromShiftID)
		to, _ := findShift(d, toShiftID)
		if from == nil {
			return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
		}
		if to == nil {
			return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
		}
		if from.ID == to.ID {
			return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
		}
		// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
		// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
		// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
		// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
		// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
		// 存在与交给自身的校验仍在其前。
		for i := range d.Handovers {
			if d.Handovers[i].FromShiftID == from.ID {
				existing := &d.Handovers[i]
				// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
				// 不影响系统保存的原交接记录。
				result = cloneHandover(*existing)
				if existing.ToShiftID != to.ID {
					return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
						ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
				}
				return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
			}
		}

		if from.Position != to.Position {
			return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
				ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
		}

		// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
		// 交班班次已经结束，重叠区间须有有效说明（正文去掉首尾空白后仍有内容，
		// 只凭说明记录存在不算）。
		if to.Closed {
			return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
		}
		if to.Start.Before(from.Start) {
			return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
				ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
				from.ID, from.Start.Format(time.RFC3339))
		}
		if !from.Closed {
			return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
				ErrShiftNotClosed, from.ID)
		}
		if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasEffectiveNote(d, from.ID, to.ID) {
			return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
				ErrOverlap, from.ID, to.ID)
		}

		entries := []HandoverEntry{}
		for i := range d.Items {
			it := &d.Items[i]
			if it.CurrentShiftID == from.ID && !it.Closed {
				entries = append(entries, HandoverEntry{
					ItemID:      it.ID,
					Content:     it.Content,
					Severity:    it.Severity,
					Constraints: it.Constraints,
					FollowOwner: it.FollowOwner,
					Status:      EntryPending,
				})
			}
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })

		d.HandoverSeq++
		now := svc.now()
		h := Handover{
			ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
			Position:    from.Position,
			FromShiftID: from.ID,
			ToShiftID:   to.ID,
			CreatedAt:   now,
			Entries:     entries,
		}
		if len(entries) == 0 {
			// 空清单直接完成。
			h.CompletedAt = &now
		}
		d.Handovers = append(d.Handovers, h)
		result = cloneHandover(h)
		saved = true
		return nil
	})
	if err != nil {
		if saved {
			// 业务校验全部通过、实际进入保存阶段后失败：内存已随快照回滚，
			// 不能把尚未保存的新交接（编号、发起时间、清单与空清单的完成时间）
			// 当作发起结果交给调用方。
			return Handover{}, err
		}
		// 业务拒绝：重复发起与改换对象仍按承诺返回保存的原记录。
		return result, err
	}
	return result, nil
}

// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
// 只有本地数据保存成功才算处理完成：输入合法、该项允许处理、实际进入保存阶段后
// 写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果（编号、岗位、
// 两班编号为空，发起时间为零值，完成时间为空，清单没有事项），不把本次尝试形成的
// 处理状态、操作人、处理时间或交接完成时间当作处理结果，也不返回失败前的整份交接；
// 最后一项的保存失败同样不能通过返回结果宣称整份交接完成。
func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
	handoverID = clean(handoverID)
	itemID = clean(itemID)
	operator = clean(operator)
	reason = clean(reason)
	trackingNote = clean(trackingNote)
	nextFollowOwner = clean(nextFollowOwner)

	if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
		return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
	}
	if err := requireNonEmpty("操作人", operator); err != nil {
		return Handover{}, err
	}

	var result Handover
	err := svc.store.mutate(func(d *Data) error {
		h, _ := findHandover(d, handoverID)
		if h == nil {
			return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
		}
		e, _ := findEntry(h, itemID)
		if e == nil {
			return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
		}
		if e.Status.Received() {
			return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
				ErrHandoverState, e.ItemID, e.Status.Label())
		}
		if e.Status == EntryReturned {
			// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
			// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
			// 操作人、退回原因或跟踪说明，也不能跳过这一步。
			return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
				ErrHandoverState, e.ItemID, h.ID)
		}
		switch action {
		case ActionReturn:
			if err := requireNonEmpty("退回原因", reason); err != nil {
				return err
			}
		case ActionTrack:
			if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
				return err
			}
			if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
				return err
			}
		}

		now := svc.now()
		switch action {
		case ActionConfirm:
			e.Status = EntryConfirmed
		case ActionTrack:
			e.Status = EntryTracking
			e.TrackingNote = trackingNote
			e.FollowOwner = nextFollowOwner
		case ActionReturn:
			e.Status = EntryReturned
			e.Rounds = append(e.Rounds, ReturnRound{
				Seq:            len(e.Rounds) + 1,
				ReturnedAt:     now,
				ReturnOperator: operator,
				Reason:         reason,
			})
		}
		e.Operator = operator
		e.ProcessedAt = &now

		if action != ActionReturn {
			// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
			if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
				it.CurrentShiftID = h.ToShiftID
				if !contains(it.ShiftIDs, h.ToShiftID) {
					it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
				}
				detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
				if action == ActionTrack {
					// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
					it.FollowOwner = nextFollowOwner
				}
				it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
			}
		}

		if h.Completed() {
			// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
			// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
			// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
			// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
			// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
			// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
			// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
			// 项无法再处理，完成时间不会被改写。
			h.CompletedAt = &now
		}
		// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
		// 与完成时间）不与系统保存的交接共享内存。
		result = cloneHandover(*h)
		return nil
	})
	if err != nil {
		// 业务拒绝或保存失败都不返回任何交接结果：保存失败时内存已随快照
		// 回滚，不能把本次尝试形成但尚未保存的处理状态、操作人、处理时间
		// 或交接完成时间当作处理结果交给调用方。
		return Handover{}, err
	}
	return result, nil
}

// validProcessedAt 报告处理时间是否真实记录：nil 或零值
// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }

func contains(xs []string, x string) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}

// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
	handoverID = clean(handoverID)
	itemID = clean(itemID)
	operator = clean(operator)
	supplement = clean(supplement)
	if err := requireNonEmpty("操作人", operator); err != nil {
		return Handover{}, err
	}
	if err := requireNonEmpty("补充说明", supplement); err != nil {
		return Handover{}, err
	}

	var result Handover
	err := svc.store.mutate(func(d *Data) error {
		h, _ := findHandover(d, handoverID)
		if h == nil {
			return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
		}
		e, _ := findEntry(h, itemID)
		if e == nil {
			return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
		}
		if e.Status != EntryReturned {
			return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
				ErrHandoverState, e.ItemID, e.Status.Label())
		}
		if len(e.Rounds) == 0 {
			return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
		}
		round := &e.Rounds[len(e.Rounds)-1]
		if round.ResubmittedAt != nil {
			return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
		}
		now := svc.now()
		round.Supplement = supplement
		round.SupplementOperator = operator
		round.SupplementAt = &now
		round.ResubmittedAt = &now
		// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
		// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
		e.Status = EntryPending
		e.Operator = ""
		e.ProcessedAt = nil
		// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
		result = cloneHandover(*h)
		return nil
	})
	return result, err
}

// GetShift 按编号查询班次。返回独立副本：改动结果不影响系统保存的记录。
func (svc *Service) GetShift(id string) (Shift, error) {
	sh, _ := findShift(&svc.store.data, clean(id))
	if sh == nil {
		return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
	}
	return cloneShift(*sh), nil
}

// ListShifts 返回全部班次，按编号排序；每个班次都是独立副本。
func (svc *Service) ListShifts() []Shift {
	out := make([]Shift, len(svc.store.data.Shifts))
	for i, sh := range svc.store.data.Shifts {
		out[i] = cloneShift(sh)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
func (svc *Service) GetItem(id string) (Item, error) {
	it, _ := findItem(&svc.store.data, clean(id))
	if it == nil {
		return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
	}
	return cloneItem(*it), nil
}

// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
func (svc *Service) GetHandover(id string) (Handover, error) {
	h, _ := findHandover(&svc.store.data, clean(id))
	if h == nil {
		return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
	}
	return cloneHandover(*h), nil
}

// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
func (svc *Service) ListHandovers() []Handover {
	out := make([]Handover, len(svc.store.data.Handovers))
	for i, h := range svc.store.data.Handovers {
		out[i] = cloneHandover(h)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// OverlapNotes 返回涉及指定班次的全部重叠说明。
func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
	shiftID = clean(shiftID)
	out := []OverlapNote{}
	for _, n := range svc.store.data.Notes {
		if n.ShiftA == shiftID || n.ShiftB == shiftID {
			out = append(out, n)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// cloneTimePtr 复制时间指针，nil 保持 nil。
func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	v := *t
	return &v
}

// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
func cloneItem(it Item) Item {
	out := it
	out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
	out.Events = append([]ItemEvent(nil), it.Events...)
	out.ClosedAt = cloneTimePtr(it.ClosedAt)
	return out
}

// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
	out := s
	out.ClosedAt = cloneTimePtr(s.ClosedAt)
	return out
}

// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
	if rec == nil {
		return nil
	}
	out := &ShiftCloseRecord{}
	if rec.Items != nil {
		out.Items = make([]CloseItemSnapshot, len(rec.Items))
		for i, s := range rec.Items {
			out.Items[i] = cloneCloseItemSnapshot(s)
		}
	}
	return out
}

// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
func cloneShift(sh Shift) Shift {
	out := sh
	out.ClosedAt = cloneTimePtr(sh.ClosedAt)
	out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
	return out
}

// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
func cloneEntry(e HandoverEntry) HandoverEntry {
	out := e
	out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
	if e.Rounds != nil {
		out.Rounds = make([]ReturnRound, len(e.Rounds))
		for i, r := range e.Rounds {
			out.Rounds[i] = r
			out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
			out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
		}
	}
	return out
}

// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
func cloneHandover(h Handover) Handover {
	out := h
	out.CompletedAt = cloneTimePtr(h.CompletedAt)
	if h.Entries != nil {
		out.Entries = make([]HandoverEntry, len(h.Entries))
		for i, e := range h.Entries {
			out.Entries[i] = cloneEntry(e)
		}
	}
	return out
}

// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
// 也不会改写这份报告；再次查询才反映最新内容。
func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
	shiftID = clean(shiftID)
	d := &svc.store.data
	rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
	sh, _ := findShift(d, shiftID)
	if sh == nil {
		return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
	}
	rep.Shift = cloneShift(*sh)

	for _, n := range d.Notes {
		if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
			rep.OverlapNotes = append(rep.OverlapNotes, n)
		}
	}
	sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })

	switch {
	case !sh.Closed:
		// 进行中的班次：事项可继续修改、关闭，展示当前信息。
		rep.Items = currentItemsOfShift(d, sh.ID)
	case sh.CloseRecord != nil:
		// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
		rep.ItemsAtClose = true
		rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
		for i, s := range sh.CloseRecord.Items {
			rep.CloseItems[i] = cloneCloseItemSnapshot(s)
		}
		sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
		for _, s := range rep.CloseItems {
			if it, _ := findItem(d, s.ItemID); it != nil {
				rep.LatestItems[s.ItemID] = cloneItem(*it)
			}
		}
	default:
		// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
		rep.HistoryIncomplete = true
		rep.Items = currentItemsOfShift(d, sh.ID)
	}
	sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
	for i := range rep.Items {
		rep.Items[i] = cloneItem(rep.Items[i])
	}

	for i := range d.Handovers {
		h := &d.Handovers[i]
		involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
		if !involved {
			continue
		}
		if h.FromShiftID == sh.ID {
			cp := cloneHandover(*h)
			rep.Outgoing = &cp
		}
		if h.ToShiftID == sh.ID {
			rep.Incoming = append(rep.Incoming, cloneHandover(*h))
		}
		for j := range h.Entries {
			rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
				HandoverID: h.ID,
				FromShift:  h.FromShiftID,
				ToShift:    h.ToShiftID,
				Entry:      cloneEntry(h.Entries[j]),
			})
		}
	}
	sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
	for k := range rep.Results {
		sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
	}
	return rep, nil
}

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath, rest, err := splitDataFlag(args, os.Getenv("HANDOVER_DATA"))
	if err != nil {
		// 显式指定了数据文件却没给出有效路径：明确失败，不回落到
		// 环境变量或默认文件，也不展示帮助或任何业务数据。
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

// valueFlags 是各子命令会带一个值的字符串参数。提取全局 --data 时，
// 这些参数后面的一个 token 是它的值：即使恰好写成 --data 或 --data=...，
// 也只是参数值（如事项内容、限制条件），不能当作数据文件参数取走。
var valueFlags = map[string]bool{
	"id": true, "position": true, "owner": true, "start": true, "end": true,
	"a": true, "b": true, "note": true, "shift": true, "content": true,
	"severity": true, "constraints": true, "follow": true, "operator": true,
	"from": true, "to": true, "item": true, "action": true, "reason": true,
	"supplement": true,
}

// splitDataFlag 从全部输入中抽出全局 --data（--data 路径 与 --data=路径 两种
// 形式，命令前后均可），返回数据文件路径与其余参数。已知参数的 --name value
// 形式中，value 原样保留，不参与 --data 判定；env 为未显式指定时的回退值。
// 显式给出 --data 却没有有效路径（--data 后为空字符串、--data= 后没有内容、
// 或命令末尾只有独立的 --data）时返回错误：这是输入错误，不能按未指定参数
// 回落到 env 或默认文件。
func splitDataFlag(args []string, env string) (dataPath string, rest []string, err error) {
	dataPath = env
	rest = make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if name, ok := flagName(arg); ok && name != "data" && valueFlags[name] {
			// 其他参数的 --name value 形式：下一个 token 是它的值，原样保留。
			rest = append(rest, arg)
			if i+1 < len(args) {
				rest = append(rest, args[i+1])
				i++
			}
			continue
		}
		switch {
		case arg == "--data":
			if i+1 >= len(args) {
				return "", nil, errors.New("--data 后缺少数据文件路径")
			}
			dataPath = args[i+1]
			i++
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		case strings.HasPrefix(arg, "--data="):
			dataPath = arg[len("--data="):]
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		default:
			rest = append(rest, arg)
		}
	}
	return dataPath, rest, nil
}

// flagName 解析 -name / --name 形式的参数名；带 = 的形式值已内联，返回 false。
func flagName(arg string) (string, bool) {
	if !strings.HasPrefix(arg, "-") || strings.Contains(arg, "=") {
		return "", false
	}
	name := strings.TrimLeft(arg, "-")
	return name, name != ""
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

package main

import (
	"reflect"
	"strings"
	"testing"
)

func TestSplitDataFlag(t *testing.T) {
	cases := []struct {
		name     string
		args     []string
		env      string
		wantPath string
		wantRest []string
	}{
		{
			name:     "内容恰为 --data=文件 时仍写入显式指定的数据文件",
			args:     []string{"--data", "甲.json", "item-add", "--shift", "S001", "--content", "--data=乙.json", "--severity", "normal", "--follow", "李四"},
			wantPath: "甲.json",
			wantRest: []string{"item-add", "--shift", "S001", "--content", "--data=乙.json", "--severity", "normal", "--follow", "李四"},
		},
		{
			name:     "内容恰为 --data 时后续独立参数仍生效",
			args:     []string{"item-add", "--shift", "S001", "--content", "--data", "--severity", "urgent", "--follow", "王五"},
			wantPath: "",
			wantRest: []string{"item-add", "--shift", "S001", "--content", "--data", "--severity", "urgent", "--follow", "王五"},
		},
		{
			name:     "限制条件恰为 --data= 开头的说明",
			args:     []string{"item-update", "--id", "I001", "--content", "正文", "--constraints", "--data=丙.json 只是说明", "--severity", "normal", "--follow", "赵六"},
			wantPath: "",
			wantRest: []string{"item-update", "--id", "I001", "--content", "正文", "--constraints", "--data=丙.json 只是说明", "--severity", "normal", "--follow", "赵六"},
		},
		{
			name:     "命令前的 --data 路径",
			args:     []string{"--data", "a.json", "shift-list"},
			wantPath: "a.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "命令后的 --data 路径",
			args:     []string{"shift-list", "--data", "a.json"},
			wantPath: "a.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "--data=路径 形式",
			args:     []string{"item-show", "--id", "I001", "--data=a.json"},
			wantPath: "a.json",
			wantRest: []string{"item-show", "--id", "I001"},
		},
		{
			name:     "未指定时沿用环境变量",
			args:     []string{"shift-list"},
			env:      "env.json",
			wantPath: "env.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "显式 --data 优先于环境变量",
			args:     []string{"--data", "explicit.json", "shift-list"},
			env:      "env.json",
			wantPath: "explicit.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "--name=value 形式的参数值不受影响",
			args:     []string{"item-add", "--shift=S001", "--content=--data=乙.json", "--severity=normal", "--follow=李四"},
			wantPath: "",
			wantRest: []string{"item-add", "--shift=S001", "--content=--data=乙.json", "--severity=normal", "--follow=李四"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path, rest, err := splitDataFlag(tc.args, tc.env)
			if err != nil {
				t.Fatalf("splitDataFlag 返回意外错误：%v", err)
			}
			if path != tc.wantPath {
				t.Errorf("dataPath = %q，期望 %q", path, tc.wantPath)
			}
			if !reflect.DeepEqual(rest, tc.wantRest) {
				t.Errorf("rest = %q，期望 %q", rest, tc.wantRest)
			}
		})
	}
}

func TestSplitDataFlagRejectsEmptyOrMissingPath(t *testing.T) {
	cases := []struct {
		name string
		args []string
		env  string
		want string
	}{
		{
			name: "命令前 --data 后为空字符串",
			args: []string{"--data", "", "shift-list"},
			want: "不能为空",
		},
		{
			name: "命令后 --data 后为空字符串",
			args: []string{"shift-list", "--data", ""},
			want: "不能为空",
		},
		{
			name: "--data= 后没有内容",
			args: []string{"shift-list", "--data="},
			want: "不能为空",
		},
		{
			name: "命令末尾只有独立 --data",
			args: []string{"shift-list", "--data"},
			want: "缺少数据文件路径",
		},
		{
			name: "空路径不能回落到环境变量",
			args: []string{"--data", "", "shift-list"},
			env:  "env.json",
			want: "不能为空",
		},
		{
			name: "空路径不能回落到环境变量（--data= 形式）",
			args: []string{"--data=", "shift-list"},
			env:  "env.json",
			want: "不能为空",
		},
		{
			name: "缺少路径不能回落到环境变量",
			args: []string{"shift-list", "--data"},
			env:  "env.json",
			want: "缺少数据文件路径",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path, rest, err := splitDataFlag(tc.args, tc.env)
			if err == nil {
				t.Fatalf("期望报错，实际成功：path=%q rest=%q", path, rest)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("错误信息应包含 %q，got %q", tc.want, err.Error())
			}
		})
	}
}

package main

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// 本文件从用户实际使用命令行的角度，为“接班班次结束后重复发起交接”建立
// 端到端回归保障：构建真实可执行程序，像用户一样逐命令调用，检查退出状态、
// 标准输出/错误输出以及数据文件的实际变化，而不是直接调用领域层接口。
//
// 覆盖的用户场景：用户建立并完成了一份非空交接（清单中既有确认接收的事项，
// 也有继续跟踪的事项），原接班班次后来也结束了；此后再用原来的交班、接班
// 编号重复发起 handover-create：
//   - 必须以退出状态 0 结束，错误输出为空，不能把“记录已存在”或“接班班次
//     已结束”报成失败；
//   - 正常输出说明已有交接记录，并完整展示原编号、交班与接班关系、发起/完成
//     时间与完整事项清单（确认接收 + 继续跟踪，含处理人、处理时间、跟踪说明
//     与当时的后续负责人），不能只给一行成功提示；
//   - 返回内容仍代表当时那次交接：各字段沿用保存的信息，事项后来改负责人、
//     被关闭都只影响最新状态，不改变重复发起展示的原清单；
//   - 操作前后保存的交接数量、事项所在班次、处理经过以及班次结束时记录全部
//     不变——即使输出正确，只要悄悄改动了业务记录（如多写一次接收）也会失败。
//
// 另外两种失败路径：把接班对象改成另一个确实存在的班次，以及填写不存在的
// 班次编号，均须非零退出、错误输出明确（改换要指出原接班班次）、正常输出不
// 宣称成功，且不产生新的交接记录。

var cliBinary string

func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "handover-e2e")
	if err != nil {
		fmt.Fprintln(os.Stderr, "创建临时目录失败:", err)
		os.Exit(1)
	}
	defer os.RemoveAll(dir)
	cliBinary = filepath.Join(dir, "handover")
	// 构建真实命令行程序；后续每个用例都以子进程方式运行它，与用户终端用法一致。
	build := exec.Command("go", "build", "-o", cliBinary, ".")
	if out, err := build.CombinedOutput(); err != nil {
		fmt.Fprintf(os.Stderr, "构建命令行程序失败: %v\n%s", err, out)
		os.Exit(1)
	}
	os.Exit(m.Run())
}

// cliResult 收集一次命令行调用的全部可观察结果。
type cliResult struct {
	exitCode int
	stdout   string
	stderr   string
}

// runCLI 以独立进程运行真实程序，显式指定数据文件，返回退出码与两路输出。
func runCLI(t *testing.T, dataPath string, args ...string) cliResult {
	t.Helper()
	full := append([]string{"--data", dataPath}, args...)
	cmd := exec.Command(cliBinary, full...)
	var out, errb bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errb
	err := cmd.Run()
	code := 0
	if ee, ok := err.(*exec.ExitError); ok {
		code = ee.ExitCode()
	} else if err != nil {
		t.Fatalf("运行命令 %v 失败：%v", args, err)
	}
	return cliResult{exitCode: code, stdout: out.String(), stderr: errb.String()}
}

// ok 断言调用成功（退出码 0、错误输出为空），返回标准输出继续校验。
func (r cliResult) ok(t *testing.T, what string) string {
	t.Helper()
	if r.exitCode != 0 {
		t.Fatalf("%s：期望退出码 0，got %d；stderr=%q", what, r.exitCode, r.stderr)
	}
	if strings.TrimSpace(r.stderr) != "" {
		t.Fatalf("%s：成功时错误输出应为空，got %q", what, r.stderr)
	}
	return r.stdout
}

// failed 断言调用失败（退出码非零、stdout 不宣称成功、stderr 含指定信息）。
func (r cliResult) failed(t *testing.T, what, wantErrSubstring string) {
	t.Helper()
	if r.exitCode == 0 {
		t.Fatalf("%s：期望非零退出码，got 0；stdout=%q", what, r.stdout)
	}
	if r.stdout != "" {
		t.Fatalf("%s：失败时正常输出不应输出内容以免宣称成功，got %q", what, r.stdout)
	}
	if wantErrSubstring != "" && !strings.Contains(r.stderr, wantErrSubstring) {
		t.Fatalf("%s：错误输出应说明 %q，got %q", what, wantErrSubstring, r.stderr)
	}
}

// hashFile 计算数据文件的 SHA-256，用于证明重复发起/失败调用不写盘改变数据。
func hashFile(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("读取数据文件 %s：%v", path, err)
	}
	return fmt.Sprintf("%x", sha256.Sum256(b))
}

// setupCompletedHandover 按用户真实步骤建立场景并返回数据文件路径：
// S001（张三，10-02 白班，已结束）-> S002（李四，夜班，随后结束）；
// H001 是非空且已完成的交接，I001 确认接收、I002 继续跟踪（带跟踪说明与
// 当时的后续负责人王五）。接收完成后、接班班次结束前，事项发生只影响“最新
// 状态”的变化：I001 后续负责人被改成赵六，I002 被李四关闭，随后接班班次结束。
func setupCompletedHandover(t *testing.T) string {
	t.Helper()
	dataPath := filepath.Join(t.TempDir(), "handover-data.json")
	must := func(what string, r cliResult) {
		t.Helper()
		r.ok(t, what)
	}

	// 建立相邻两班（端点相接，无需重叠说明）。
	must("建立交班班次", runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "张三",
		"--start", "2026-10-02T08:00:00+08:00", "--end", "2026-10-02T16:00:00+08:00"))
	must("建立接班班次", runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "李四",
		"--start", "2026-10-02T16:00:00+08:00", "--end", "2026-10-02T23:00:00+08:00"))

	// 交班班次在班期间留下两项未关闭事项（一项重要、一项普通）。
	must("新增重要事项", runCLI(t, dataPath,
		"item-add", "--shift", "S001", "--content", "一号泵压力异常待复核",
		"--severity", "important", "--constraints", "需停电窗口", "--follow", "李四"))
	must("新增跟踪事项", runCLI(t, dataPath,
		"item-add", "--shift", "S001", "--content", "巡检台账补录",
		"--severity", "normal", "--follow", "李四"))

	// 原交班班次结束后才能发起首次交接。
	must("结束交班班次", runCLI(t, dataPath, "shift-close", "--id", "S001"))
	must("首次发起交接", runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002"))

	// 接班人逐项处理：I001 确认接收；I002 先退回、补充后再继续跟踪，覆盖确认
	// 与跟踪两种已接收结果，并保留一轮退回/补充历史。
	must("确认接收 I001", runCLI(t, dataPath,
		"handover-process", "--id", "H001", "--item", "I001",
		"--action", "confirm", "--operator", "李四"))
	must("退回 I002", runCLI(t, dataPath,
		"handover-process", "--id", "H001", "--item", "I002",
		"--action", "return", "--operator", "李四", "--reason", "需要补充台账口径"))
	must("补充并重新提交 I002", runCLI(t, dataPath,
		"handover-resubmit", "--id", "H001", "--item", "I002",
		"--operator", "张三", "--supplement", "台账口径已对齐"))
	must("继续跟踪 I002", runCLI(t, dataPath,
		"handover-process", "--id", "H001", "--item", "I002",
		"--action", "track", "--operator", "李四",
		"--note", "持续盯压并复测", "--follow", "王五"))

	// 接收完成之后、接班班次结束之前，事项发生只影响“最新状态”的变化：
	// I001 后续负责人被改为赵六；I002 被关闭。这些都不能改写已保存的交接清单。
	must("接收后修改 I001 后续负责人", runCLI(t, dataPath,
		"item-update", "--id", "I001", "--content", "一号泵压力异常待复核",
		"--severity", "important", "--constraints", "需停电窗口", "--follow", "赵六"))
	must("接班班次结束前关闭 I002", runCLI(t, dataPath, "item-close", "--id", "I002", "--operator", "李四"))
	must("结束接班班次", runCLI(t, dataPath, "shift-close", "--id", "S002"))

	return dataPath
}

// TestCLIRepeatHandoverAfterReceiverClosedReturnsSavedRecord 是核心保障：
// 接班班次结束后用原编号重复发起，必须成功且原样返回保存的交接记录，
// 且数据文件不发生任何变化。
func TestCLIRepeatHandoverAfterReceiverClosedReturnsSavedRecord(t *testing.T) {
	dataPath := setupCompletedHandover(t)

	// 重复发起前，用只读命令 handover-show 取得保存的原交接完整输出作为基准。
	baseShow := runCLI(t, dataPath, "handover-show", "--id", "H001")
	wantShow := baseShow.ok(t, "查询原交接 H001")
	if !strings.Contains(wantShow, "已完成") {
		t.Fatalf("前置交接应已完成，handover-show 输出：\n%s", wantShow)
	}
	before := hashFile(t, dataPath)

	// 接班班次结束后用原来的交班、接班编号再次发起。
	res := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002")
	repeatOut := res.ok(t, "接班班次结束后重复发起")

	// 正常输出首先说明这是已有记录的重复发起（而不是把它当成一次新交接）。
	if !strings.Contains(repeatOut, "已存在交接记录") {
		t.Fatalf("输出应说明已有交接记录（重复发起返回已有记录），got:\n%s", repeatOut)
	}
	// 不能只给一行成功提示：去掉首行提示后，必须包含与 handover-show 完全
	// 一致的完整交接内容（原编号、两班关系、时间、完整事项清单与处理结果）。
	body := repeatOut
	if i := strings.Index(body, "\n"); i >= 0 {
		body = body[i+1:]
	}
	body = strings.TrimRight(body, "\n")
	wantBody := strings.TrimRight(wantShow, "\n")
	if body != wantBody {
		var dfr bytes.Buffer
		dfr.WriteString("重复发起展示的交接内容必须与保存的原记录一致：\n")
		if len(body) == 0 {
			dfr.WriteString("重复发起只输出了一行提示，省略了交接内容。\n")
		}
		dfr.WriteString(fmt.Sprintf("--- handover-show 保存的原记录 ---\n%s\n", wantBody))
		dfr.WriteString(fmt.Sprintf("--- 重复发起实际输出 ---\n%s\n", body))
		t.Fatal(dfr.String())
	}

	// 关键防回归点：输出正确不代表数据没被改动。比对整个数据文件的哈希，
	// 任何重新生成清单、重新接收（多一条 received 事件）、移动事项所在班次、
	// 改写完成时间或结束时记录都会在这里暴露。
	after := hashFile(t, dataPath)
	if after != before {
		t.Fatalf("重复发起不得改动数据文件：before=%s after=%s", before, after)
	}
}

// TestCLIRepeatHandoverShowsHistoricalValues 保证重复发起返回的是当时那次
// 交接的内容：原编号、两班关系、确认与跟踪的处理人、跟踪说明与当时的后续
// 负责人，都不因事项后来的变化而改变。
func TestCLIRepeatHandoverShowsHistoricalValues(t *testing.T) {
	dataPath := setupCompletedHandover(t)

	out := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002").ok(t, "重复发起")

	for _, want := range []string{
		"H001", "S001 -> S002",
		// 两项事项与两种接收结果都要展示，不能按交班班次当前剩余事项重新生成。
		"I001  [确认接收]",
		"I002  [继续跟踪]",
		// 处理人沿用保存信息；跟踪说明与当时的后续负责人保留当时值。
		"处理人=李四", "持续盯压并复测", "跟踪后续负责人：王五",
		// 退回/补充历史仍属于当时那次交接。
		"第1次退回", "台账口径已对齐",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("重复发起输出应保留当时交接信息 %q，got:\n%s", want, out)
		}
	}
	// I001 接收后负责人已被改为赵六，但原清单保存的仍是发起交接时的李四。
	i001Block := out[strings.Index(out, "I001"):strings.Index(out, "I002")]
	if !strings.Contains(i001Block, "后续负责人=李四") || strings.Contains(i001Block, "赵六") {
		t.Fatalf("I001 应保留接收时清单里的原后续负责人李四，不能被最新负责人赵六替换：\n%s", i001Block)
	}
	// 交班班次当前已无未关闭事项（早已全部接收），不能按它当前还留下多少
	// 事项重新生成清单——输出里必须仍是原来的 2 项。
	if strings.Count(out, "\n  I00") != 2 {
		t.Fatalf("应完整展示原清单的2项，而不是按交班班次当前状态重新生成，got:\n%s", out)
	}
}

// TestCLIRepeatHandoverLatestItemChangesDoNotAffectRecord 验证“最新状态 vs
// 历史清单”对照：事项后来的负责人修改/关闭只影响最新状态，重复发起仍保留
// 接收时的原清单与历史信息。
func TestCLIRepeatHandoverLatestItemChangesDoNotAffectRecord(t *testing.T) {
	dataPath := setupCompletedHandover(t)

	// item-show 反映事项最新状态（I002 已关闭、当前班次 S002、负责人为王五）；
	// 重复发起的交接清单里 I002 仍是当时的“继续跟踪”，后续负责人仍为王五。
	journey := runCLI(t, dataPath, "item-show", "--id", "I002").ok(t, "查询 I002 最新状态")
	if !strings.Contains(journey, "已关闭") || !strings.Contains(journey, "当前班次=S002") {
		t.Fatalf("I002 最新状态应为 S002 班次上已关闭，got:\n%s", journey)
	}
	out := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002").ok(t, "重复发起")
	if !strings.Contains(out, "I002  [继续跟踪]") {
		t.Fatalf("重复发起应保留 I002 接收时的继续跟踪结果，got:\n%s", out)
	}
	i002Block := out[strings.Index(out, "I002"):]
	if !strings.Contains(i002Block, "跟踪后续负责人：王五") || !strings.Contains(i002Block, "跟踪说明：持续盯压并复测") {
		t.Fatalf("I002 应保留接收时的后续负责人王五与跟踪说明，got:\n%s", i002Block)
	}
}

// TestCLIHandoverCountAndCloseRecordUnchanged 保障重复发起前后，保存的交接
// 数量、班次结束时记录与事项处理经过保持一致，事项历史不能多出一次接收。
func TestCLIHandoverCountAndCloseRecordUnchanged(t *testing.T) {
	dataPath := setupCompletedHandover(t)

	listBefore := runCLI(t, dataPath, "handover-list").ok(t, "重复前列出交接")
	showS002Before := runCLI(t, dataPath, "shift-show", "--id", "S002").ok(t, "重复前查看接班班次结束时记录")
	journeyBefore := runCLI(t, dataPath, "item-show", "--id", "I001").ok(t, "重复前 I001 处理经过")
	beforeHash := hashFile(t, dataPath)

	runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002").ok(t, "重复发起")

	listAfter := runCLI(t, dataPath, "handover-list").ok(t, "重复后列出交接")
	showS002After := runCLI(t, dataPath, "shift-show", "--id", "S002").ok(t, "重复后查看接班班次结束时记录")
	journeyAfter := runCLI(t, dataPath, "item-show", "--id", "I001").ok(t, "重复后 I001 处理经过")

	// 仍只有原 H001 一条交接，数量不增加。
	if strings.Count(listAfter, "H001") != 1 || strings.Contains(listAfter, "H002") {
		t.Fatalf("应仍只有原 H001 一条交接，got:\n%s", listAfter)
	}
	if listBefore != listAfter {
		t.Fatalf("重复发起后交接清单不应变化：\nbefore:\n%s\nafter:\n%s", listBefore, listAfter)
	}
	// 班次结束时记录不变化（文本一致）。
	if showS002Before != showS002After {
		t.Fatalf("重复发起不得改变班次 S002 的结束时记录：\nbefore:\n%s\nafter:\n%s", showS002Before, showS002After)
	}
	// 事项处理经过不变化：接收只发生过一次，重复查询得到的时间线完全一致。
	if journeyBefore != journeyAfter {
		t.Fatalf("重复发起不得追加处理经过（不能多一次接收）：\nbefore:\n%s\nafter:\n%s", journeyBefore, journeyAfter)
	}
	// 整体数据文件也不能变（兜底，捕获任何未单独比对到的字段改动）。
	if afterHash := hashFile(t, dataPath); afterHash != beforeHash {
		t.Fatalf("重复发起后数据文件发生了变化：before=%s after=%s", beforeHash, afterHash)
	}
}

// TestCLIExistingHandoverRejectsDifferentExistingShift 已有交接只允许原接班
// 对象：改成另一个确实存在的班次（分别覆盖已结束与未结束）必须失败，错误
// 输出指出原接班班次，stdout 不宣称成功，且不产生新交接。
func TestCLIExistingHandoverRejectsDifferentExistingShift(t *testing.T) {
	dataPath := setupCompletedHandover(t)

	// 另一个确实存在且已结束的同岗位班次。
	runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "钱七",
		"--start", "2026-10-03T08:00:00+08:00", "--end", "2026-10-03T16:00:00+08:00").ok(t, "建立第三个班次")
	runCLI(t, dataPath, "shift-close", "--id", "S003").ok(t, "结束第三个班次")
	// 基线哈希取在额外班次建立之后：失败的 handover-create 本身不应写任何数据。
	before := hashFile(t, dataPath)

	// 已结束的新接班对象。失败后立即比对，文件不应有任何改动。
	r1 := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S003")
	r1.failed(t, "改换为已结束的现存班次", "不能改换接班对象")
	if !strings.Contains(r1.stderr, "S002") {
		t.Fatalf("错误输出应指出原接班班次 S002，got %q", r1.stderr)
	}
	if after := hashFile(t, dataPath); after != before {
		t.Fatalf("第一次改换对象失败不得改变数据文件：before=%s after=%s", before, after)
	}

	// 另一个确实存在且尚未结束的同岗位班次。
	runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "孙八",
		"--start", "2026-10-03T16:00:00+08:00", "--end", "2026-10-04T00:00:00+08:00").ok(t, "建立第四个班次")
	beforeOpen := hashFile(t, dataPath)
	r2 := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S004")
	r2.failed(t, "改换为未结束的现存班次", "不能改换接班对象")
	if !strings.Contains(r2.stderr, "S002") {
		t.Fatalf("错误输出应指出原接班班次 S002，got %q", r2.stderr)
	}
	if after := hashFile(t, dataPath); after != beforeOpen {
		t.Fatalf("第二次改换对象失败不得改变数据文件：before=%s after=%s", beforeOpen, after)
	}

	// 两次失败都不得产生新交接。
	list := runCLI(t, dataPath, "handover-list").ok(t, "失败后列出交接")
	if strings.Count(list, "H001") != 1 || strings.Contains(list, "H002") {
		t.Fatalf("改换对象失败后不应产生新交接，got:\n%s", list)
	}
}

// TestCLIExistingHandoverRejectsNonexistentShift 填写不存在的班次编号必须
// 明确报不存在，非零退出、stdout 不宣称成功，且不产生新交接。
func TestCLIExistingHandoverRejectsNonexistentShift(t *testing.T) {
	dataPath := setupCompletedHandover(t)
	before := hashFile(t, dataPath)

	r := runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S999")
	r.failed(t, "接班编号不存在", "不存在")
	if !strings.Contains(r.stderr, "S999") {
		t.Fatalf("错误输出应指出不存在的编号 S999，got %q", r.stderr)
	}

	// 交班编号不存在同样明确报错。
	r2 := runCLI(t, dataPath, "handover-create", "--from", "S998", "--to", "S002")
	r2.failed(t, "交班编号不存在", "不存在")
	if !strings.Contains(r2.stderr, "S998") {
		t.Fatalf("错误输出应指出不存在的编号 S998，got %q", r2.stderr)
	}

	list := runCLI(t, dataPath, "handover-list").ok(t, "失败后列出交接")
	if strings.Count(list, "H001") != 1 || strings.Contains(list, "H002") {
		t.Fatalf("编号不存在失败后不应产生新交接，got:\n%s", list)
	}
	if after := hashFile(t, dataPath); after != before {
		t.Fatalf("编号不存在失败后数据文件不应变化：before=%s after=%s", before, after)
	}
}

//     也不以班次负责人或处理经过中的信息代替；
//   - 两者都有记录时沿用原有“姓名 于 时间”格式。
func formatClosedState(prefix, operator string, closedAt *time.Time) string {
	hasOperator := operator != ""
	hasTime := closedAt != nil && !closedAt.IsZero()
	switch {
	case hasOperator && hasTime:
		return fmt.Sprintf("%s（%s 于 %s）", prefix, operator, fmtTime(*closedAt))
	case hasOperator:
		return fmt.Sprintf("%s（关闭人 %s，关闭时间未记录）", prefix, operator)
	case hasTime:
		return fmt.Sprintf("%s（关闭人未记录，关闭时间 %s）", prefix, fmtTime(*closedAt))
	default:
		return prefix + "（关闭人未记录，关闭时间未记录）"
	}
}

// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
// 经过查询（item-show）共用的同一条业务规则。
//
// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
//
// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
func currentProcessing(e HandoverEntry) (operator, processedAt string) {
	if e.Status == EntryPending {
		return "尚未处理", "尚未处理"
	}
	return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
}

// returnRoundView 是一轮退回历史在展示层的统一解读。交接查询
// （handover-show，及 shift-show 报告内嵌的交接清单）与班次报告末尾
// “各项交接当前结果”两处共用同一份判断，只保留各自的措辞、缩进与
// 字段次序——统一维护的是共同规则，不是把两处改成同一种文本。
type returnRoundView struct {
	Seq            int
	ReturnedAt     string // 退回时间：真实值用带时区格式；缺失或零值显示未记录
	ReturnOperator string // 退回人：有值保留原姓名，缺失显示未记录
	Reason         string // 该轮保存的退回原因，原样展示

	HasSupplement      bool   // 该轮是否保存了非空补充说明；没有就不产生补充段落
	Supplement         string // 该轮保存的补充说明
	SupplementOperator string // 补充人：缺失显示未记录
	SupplementAt       string // 补充时间：缺失（nil）或零值显示未记录

	Resubmitted   bool   // 该轮是否保存了重新提交时间（旧数据零值也算已重新提交）
	ResubmittedAt string // 重新提交时间：零值显示未记录；未保存时不展示该行
}

// viewReturnRound 按共同规则解读一轮已保存的退回历史。它只做展示判断，
// 不补齐、不推测：
//   - 姓名有值保留原姓名、缺失显示未记录；时间缺失或为旧数据零值
//     （0001-01-01T00:00:00Z）显示未记录，真实时间沿用带时区格式，
//     姓名与时间各自独立判断，缺一个不隐藏另一个；
//   - 不用班次负责人、交接发起时间、当前处理人或其他轮次的资料补齐
//     本轮记录；
//   - 该轮没有非空补充说明时不产生补充段落；没有重新提交时间时不显示
//     已重新提交；保存了零值重新提交时间仍按已重新提交展示、时间显示
//     未记录，不悄悄改成尚未提交。
func viewReturnRound(r ReturnRound) returnRoundView {
	v := returnRoundView{
		Seq:            r.Seq,
		ReturnedAt:     fmtTimeIfRecorded(r.ReturnedAt),
		ReturnOperator: whoIfRecorded(r.ReturnOperator),
		Reason:         r.Reason,
		Resubmitted:    r.ResubmittedAt != nil,
		ResubmittedAt:  fmtTimePtrIfRecorded(r.ResubmittedAt),
	}
	if r.Supplement != "" {
		v.HasSupplement = true
		v.Supplement = r.Supplement
		v.SupplementOperator = whoIfRecorded(r.SupplementOperator)
		v.SupplementAt = fmtTimePtrIfRecorded(r.SupplementAt)
	}
	return v
}

// viewReturnRounds 按保存次序解读全部退回轮次，不增删、不重排、不补造：
// 连续发生多轮退回时每轮各用各的退回原因与补充说明，前一轮的原因和
// 补充不会被后一轮替换；没有退回轮次时返回空切片，调用方不补造轮次。
func viewReturnRounds(rounds []ReturnRound) []returnRoundView {
	vs := make([]returnRoundView, len(rounds))
	for i, r := range rounds {
		vs[i] = viewReturnRound(r)
	}
	return vs
}

// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
func entryCurrentResultLabel(s EntryStatus) string {
	switch s {
	case EntryPending:
		return "待处理（接班人尚未处理）"
	case EntryReturned:
		return "退回（等待交班人补充）"
	case EntryConfirmed:
		return "确认接收"
	case EntryTracking:
		return "继续跟踪（已接收）"
	case "":
		return "处理结果未记录"
	}
	return "处理结果无法识别（原值：" + string(s) + "）"
}

// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
func FormatJourneyEvent(ev JourneyEvent) string {
	when := "未记录"
	if ev.TimeKnown {
		when = fmtTime(ev.At)
	}
	who := whoIfRecorded(ev.Operator)
	where := ""
	if ev.HandoverID != "" {
		where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
	}
	switch ev.Kind {
	case "created":
		return when + " 事项建立"
	case "updated":
		return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
	case "closed":
		return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
	case "received":
		return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
	case "handover-init":
		// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
		return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
	case "return":
		return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
			when, where, ev.RoundSeq, who, ev.Reason)
	case "return-incomplete":
		// 当前结果是退回却没有退回轮次记录：退回确实发生过，但轮次序号、
		// 退回原因、补充与重新提交经过都没有可靠记录。处理人与时间各自使用
		// 当前保存的信息（缺失分别标为未记录），并明确提示退回历史不完整、
		// 原因未记录，不编造第几次退回，也不拿事项内容代替原因。
		return fmt.Sprintf("%s %s退回 操作人=%s（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
			when, where, who)
	case "resubmit":
		return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
			when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
			whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
	case "confirm":
		return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
	case "track":
		return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
			when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
	}
	return when + " " + ev.Kind
}

// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
func FormatItemJourney(j ItemJourney) string {
	var b strings.Builder
	writeItemHeader(&b, j.Item)

	b.WriteString("  处理经过：\n")
	if len(j.Events) == 0 {
		b.WriteString("    （暂无记录）\n")
	}
	for _, ev := range j.Events {
		b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
	}

	b.WriteString("  交接当前结果：\n")
	if !j.HasHandovers {
		b.WriteString("    暂无交接记录\n")
	}
	for _, r := range j.Results {
		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）。
		operator, processedAt := currentProcessing(r.Entry)
		fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
			r.HandoverID, r.FromShift, r.ToShift,
			entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
	}
	return b.String()
}

// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
	var b strings.Builder
	state := "结束时未关闭"
	if snap.Closed {
		state = formatClosedState("结束时已关闭", snap.CloseOperator, snap.ClosedAt)
	}
	fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
	fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
	fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
	fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
	if latest == nil {
		b.WriteString("  最新状态：事项记录已不存在\n")
		return b.String()
	}
	closeState := "未关闭"
	if latest.Closed {
		closeState = formatClosedState("已关闭", latest.CloseOperator, latest.ClosedAt)
	}
	fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
		latest.CurrentShiftID, latest.FollowOwner, closeState)
	return b.String()
}

// FormatOverlapNote 格式化重叠说明。
func FormatOverlapNote(n OverlapNote) string {
	return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
		n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
}

// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
func FormatEntry(e HandoverEntry) string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
		e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
	fmt.Fprintf(&b, "  原文：%s\n", e.Content)
	fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
	// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）；
	// 待处理项在此额外说明等待接班人处理。
	operator, processedAt := currentProcessing(e)
	if e.Status == EntryPending {
		fmt.Fprintf(&b, "  最后处理：尚未处理（等待接班人处理）；处理人=%s；处理时间=%s\n",
			operator, processedAt)
	} else {
		fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n", operator, processedAt)
	}
	if e.Status == EntryTracking || e.TrackingNote != "" {
		fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
		fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
	}
	// 逐轮退回、补充与重新提交沿用共用的退回历史解读规则
	// （见 viewReturnRound），保留本处原有措辞、缩进与字段次序。
	for _, r := range viewReturnRounds(e.Rounds) {
		fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
			r.Seq, r.ReturnedAt, r.ReturnOperator, r.Reason)
		if r.HasSupplement {
			fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
				r.Supplement, r.SupplementOperator, r.SupplementAt)
		}
		if r.Resubmitted {
			fmt.Fprintf(&b, "    已重新提交：%s\n", r.ResubmittedAt)
		}
	}
	return b.String()
}

// FormatHandover 格式化完整交接记录。
func FormatHandover(h Handover) string {
	var b strings.Builder
	state := "未完成"
	if h.Completed() {
		state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
	}
	fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
		h.ID, h.Position, h.FromShiftID, h.ToShiftID,
		fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
	if len(h.Entries) == 0 {
		b.WriteString("  （空清单，直接完成）\n")
	}
	for i := range h.Entries {
		b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
	}
	return b.String()
}

func indentLines(s, prefix string) string {
	return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
}

